import { Component } from '@angular/core';
 

@Component({
  selector: 'app-tabs',
  templateUrl: 'tabs.page.html',
  styleUrls: ['tabs.page.scss']
})
export class TabsPage {

  constructor() {}

}
<ion-tabs>

  <ion-tab-bar class="menu-inferior" slot="button">
    <ion-tab-button tab="tab1" href="./tabs/tab1">
      <ion-icon class="icono-menu" name="list-circle-outline"></ion-icon>
    </ion-tab-button>

    <ion-tab-button tab="tab2" href="/tabs/tab2">
      <ion-icon class="icono-menu" name="chatbubbles-outline"></ion-icon>
    </ion-tab-button>

    <ion-tab-button tab="tab3" href="/tabs/tab3">
      <ion-icon class="icono-menu" name="person-circle-outline"></ion-icon>
    </ion-tab-button>
  </ion-tab-bar>

</ion-tabs>
